1	"use client";
2	
3	import Link from "next/link";
4	import { usePathname } from "next/navigation";
5	import { useEffect, useRef, useState } from "react";
6	import { NxLogo } from "./Logo";
7	import { ClaudeMark } from "./ClaudeMark";
8	import {
9	  IconServer,
10	  IconGame,
11	  IconSpark,
12	  IconDisk,
13	  IconNetwork,
14	  IconGlobe,
15	  IconMail,
16	  IconCode,
17	  IconArrow,
18	} from "./icons";
19	
20	/**
21	 * Marketing top nav (v2 redesign). A grouped structure instead of a flat link
22	 * list: a Products mega-menu organized by outcome (Compute / Storage & Network /
23	 * Web Essentials) plus a "by use case" rail, then Pricing · Compare · Blog and a
24	 * Company dropdown. One prominent primary CTA; a live Status pill on the right.
25	 */
26	
27	type Item = { label: string; href: string; desc: string; icon: (p: { size?: number }) => React.ReactNode; badge?: string };
28	
29	const PRODUCT_GROUPS: { title: string; items: Item[] }[] = [
30	  {
31	    title: "Compute",
32	    items: [
33	      { label: "VPS Hosting", href: "/vps", desc: "Full-root NVMe KVM servers", icon: IconServer },
34	      { label: "Game Servers", href: "/game-servers", desc: "Minecraft, Rust, Valheim & more", icon: IconGame },
35	      { label: "Claude AI Builder", href: "/features", desc: "Build your server in plain English", icon: ClaudeMark, badge: "New" },
36	    ],
37	  },
38	  {
39	    title: "Storage & Network",
40	    items: [
41	      { label: "Block Storage", href: "/block-storage", desc: "Add-on NVMe volumes", icon: IconDisk },
42	      { label: "Dedicated IPv4", href: "/vps", desc: "A clean, static IP per server", icon: IconNetwork },
43	    ],
44	  },
45	  {
46	    title: "Web Essentials",
47	    items: [
48	      { label: "Domains", href: "/domains", desc: "Register & manage domains", icon: IconGlobe },
49	      { label: "Business Email", href: "/business-email", desc: "Mailboxes on your own domain", icon: IconMail },
50	    ],
51	  },
52	];
53	
54	const USE_CASES: Item[] = [
55	  { label: "Vibe coding", href: "/vibe-coding", desc: "Build sites & apps, no code", icon: IconSpark, badge: "New" },
56	  { label: "Free tools", href: "/tools", desc: "WHOIS, DNS, SSL & more", icon: IconNetwork, badge: "Free" },
57	  { label: "Migrate to Nxeon", href: "/migrate", desc: "Free — bring your servers", icon: IconArrow },
58	  { label: "Developers & API", href: "/developers", desc: "Automate everything", icon: IconCode },
59	  { label: "AI apps & agents", href: "/features", desc: "Ship agents in minutes", icon: IconSpark },
60	];
61	
62	const COMPANY: { label: string; href: string }[] = [
63	  { label: "About", href: "/about" },
64	  { label: "Security", href: "/security" },
65	  { label: "Contact", href: "/contact" },
66	  { label: "Affiliate program", href: "/affiliate" },
67	  { label: "Status", href: "/status" },
68	];
69	
70	export function MarketingHeader() {
71	  const pathname = usePathname();
72	  const [open, setOpen] = useState(false); // mobile drawer
73	  const [menu, setMenu] = useState<null | "products" | "company">(null); // desktop dropdown
74	  const [scrolled, setScrolled] = useState(false);
75	  const [authed, setAuthed] = useState(false);
76	  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
77	
78	  // Show "Back to portal" for a signed-in visitor while keeping marketing pages
79	  // static. Two-step, after mount: (1) optimistic read of the non-httpOnly
80	  // `nxeon_authed` flag cookie (instant, no flash when present), then (2) an
81	  // authoritative probe to /api/auth/status which reads the real session cookie
82	  // server-side — so it's correct even if the flag cookie is missing or stale.
83	  useEffect(() => {
84	    setAuthed(document.cookie.split("; ").some((c) => c.startsWith("nxeon_authed=")));
85	    let alive = true;
86	    fetch("/api/auth/status", { cache: "no-store" })
87	      .then((r) => (r.ok ? r.json() : null))
88	      .then((d) => {
89	        if (alive && d && typeof d.authed === "boolean") setAuthed(d.authed);
90	      })
91	      .catch(() => {});
92	    return () => {
93	      alive = false;
94	    };
95	  }, []);
96	
97	  useEffect(() => {
98	    const onScroll = () => setScrolled(window.scrollY > 8);
99	    onScroll();
100	    window.addEventListener("scroll", onScroll, { passive: true });
101	    return () => window.removeEventListener("scroll", onScroll);
102	  }, []);
103	
104	  useEffect(() => {
105	    setOpen(false);
106	    setMenu(null);
107	  }, [pathname]);
108	
109	  // Hover-intent: brief close delay so diagonal mouse travel to the panel doesn't drop it.
110	  const openMenu = (m: "products" | "company") => {
111	    if (closeTimer.current) clearTimeout(closeTimer.current);
112	    setMenu(m);
113	  };
114	  const scheduleClose = () => {
115	    if (closeTimer.current) clearTimeout(closeTimer.current);
116	    closeTimer.current = setTimeout(() => setMenu(null), 120);
117	  };
118	
119	  return (
120	    <header
121	      className={`sticky top-0 z-50 border-b transition-colors duration-300 ${
122	        scrolled || menu ? "border-white/[0.06] bg-navy-950/85 backdrop-blur-xl" : "border-transparent bg-transparent"
123	      }`}
124	      onMouseLeave={scheduleClose}
125	    >
126	      <div className="rail flex h-[72px] items-center justify-between">
127	        <Link href="/" aria-label="Nxeon home" className="shrink-0">
128	          <NxLogo id="hdr" size={44} />
129	        </Link>
130	
131	        {/* Desktop nav */}
132	        <nav className="hidden items-center gap-1 lg:flex">
133	          <button
134	            className={`nav-trigger ${menu === "products" ? "is-open" : ""}`}
135	            onMouseEnter={() => openMenu("products")}
136	            onFocus={() => openMenu("products")}
137	            aria-expanded={menu === "products"}
138	          >
139	            Products <Chevron open={menu === "products"} />
140	          </button>
141	          <TopLink href="/pricing" pathname={pathname}>Pricing</TopLink>
142	          <TopLink href="/compare" pathname={pathname}>Compare</TopLink>
143	          <TopLink href="/blog" pathname={pathname}>Blog</TopLink>
144	          <button
145	            className={`nav-trigger ${menu === "company" ? "is-open" : ""}`}
146	            onMouseEnter={() => openMenu("company")}
147	            onFocus={() => openMenu("company")}
148	            aria-expanded={menu === "company"}
149	          >
150	            Company <Chevron open={menu === "company"} />
151	          </button>
152	        </nav>
153	
154	        <div className="hidden items-center gap-2 lg:flex">
155	          <Link href="/status" className="flex items-center gap-1.5 rounded-full border border-white/[0.07] px-2.5 py-1 text-xs text-slate-400 transition-colors hover:text-white">
156	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />
157	            Status
158	          </Link>
159	          {authed ? (
160	            <>
161	              <Link href="/dashboard/settings" className="btn-ghost">My account</Link>
162	              <Link href="/dashboard" className="btn-primary">Back to portal</Link>
163	            </>
164	          ) : (
165	            <>
166	              <Link href="/login" className="btn-ghost">Log in</Link>
167	              <Link href="/register" className="btn-primary">Get started</Link>
168	            </>
169	          )}
170	        </div>
171	
172	        <button
173	          className="btn-ghost rounded-lg p-2 lg:hidden"
174	          aria-label="Toggle menu"
175	          aria-expanded={open}
176	          onClick={() => setOpen((v) => !v)}
177	        >
178	          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
179	            {open ? <path d="M6 6l12 12M18 6 6 18" /> : <path d="M4 7h16M4 12h16M4 17h16" />}
180	          </svg>
181	        </button>
182	      </div>
183	
184	      {/* Desktop mega-menu panels */}
185	      {menu === "products" && (
186	        <div
187	          className="absolute inset-x-0 top-full hidden lg:block"
188	          onMouseEnter={() => openMenu("products")}
189	          onMouseLeave={scheduleClose}
190	        >
191	          <div className="rail pb-6">
192	            <div className="grid grid-cols-[1.1fr_1.1fr_1.1fr_0.9fr] gap-2 rounded-2xl border border-white/10 bg-navy-950/95 p-3 shadow-2xl backdrop-blur-2xl">
193	              {PRODUCT_GROUPS.map((g) => (
194	                <div key={g.title} className="p-2">
195	                  <p className="section-label mb-2 px-2">{g.title}</p>
196	                  <div className="space-y-0.5">
197	                    {g.items.map((it) => (
198	                      <MegaItem key={it.label} item={it} />
199	                    ))}
200	                  </div>
201	                </div>
202	              ))}
203	              <div className="rounded-xl bg-white/[0.02] p-2">
204	                <p className="section-label mb-2 px-2">By use case</p>
205	                <div className="space-y-0.5">
206	                  {USE_CASES.map((it) => (
207	                    <MegaItem key={it.label} item={it} />
208	                  ))}
209	                </div>
210	                <div className="mx-2 my-2 border-t border-white/[0.06]" />
211	                <Link href="/features" className="flex items-center justify-between rounded-lg px-2 py-2 text-sm text-brand-300 hover:bg-white/[0.04]">
212	                  All features <IconArrow size={15} />
213	                </Link>
214	              </div>
215	            </div>
216	          </div>
217	        </div>
218	      )}
219	
220	      {menu === "company" && (
221	        <div
222	          className="absolute inset-x-0 top-full hidden lg:block"
223	          onMouseEnter={() => openMenu("company")}
224	          onMouseLeave={scheduleClose}
225	        >
226	          <div className="rail flex justify-end pb-6">
227	            <div className="w-56 rounded-2xl border border-white/10 bg-navy-950/95 p-2 shadow-2xl backdrop-blur-2xl">
228	              {COMPANY.map((l) => (
229	                <Link key={l.href} href={l.href} className="flex items-center justify-between rounded-lg px-3 py-2 text-sm text-slate-300 hover:bg-white/[0.05] hover:text-white">
230	                  {l.label}
231	                  {l.label === "Status" && <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />}
232	                </Link>
233	              ))}
234	            </div>
235	          </div>
236	        </div>
237	      )}
238	
239	      {/* Mobile drawer */}
240	      {open && (
241	        <div className="border-t border-white/[0.06] bg-navy-950/95 backdrop-blur-xl lg:hidden">
242	          <nav className="rail flex max-h-[70vh] flex-col gap-1 overflow-y-auto py-4">
243	            {PRODUCT_GROUPS.map((g) => (
244	              <div key={g.title} className="mb-1">
245	                <p className="section-label px-3 pb-1 pt-2">{g.title}</p>
246	                {g.items.map((it) => (
247	                  <Link key={it.label} href={it.href} className="flex items-center gap-3 rounded-lg px-3 py-2 text-sm text-slate-300 hover:bg-white/[0.05] hover:text-white">
248	                    <span className="text-brand-300">{it.icon({ size: 18 })}</span>
249	                    {it.label}
250	                    {it.badge && <span className="rounded-full bg-brand-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-brand-200">{it.badge}</span>}
251	                  </Link>
252	                ))}
253	              </div>
254	            ))}
255	            <div className="my-1 border-t border-white/[0.06]" />
256	            {[{ label: "Pricing", href: "/pricing" }, { label: "Compare", href: "/compare" }, { label: "Blog", href: "/blog" }, ...COMPANY].map((l) => (
257	              <Link key={l.href} href={l.href} className="rounded-lg px-3 py-2.5 text-sm font-medium text-slate-300 hover:bg-white/[0.05] hover:text-white">
258	                {l.label}
259	              </Link>
260	            ))}
261	            <div className="mt-2 flex flex-col gap-2 border-t border-white/[0.06] pt-3">
262	              {authed ? (
263	                <>
264	                  <Link href="/dashboard/settings" className="btn-secondary w-full">My account</Link>
265	                  <Link href="/dashboard" className="btn-primary w-full">Back to portal</Link>
266	                </>
267	              ) : (
268	                <>
269	                  <Link href="/login" className="btn-secondary w-full">Log in</Link>
270	                  <Link href="/register" className="btn-primary w-full">Get started</Link>
271	                </>
272	              )}
273	            </div>
274	          </nav>
275	        </div>
276	      )}
277	    </header>
278	  );
