282	  const active = pathname === href;
283	  return (
284	    <Link href={href} className={`rounded-lg px-3 py-2 text-sm font-medium transition-colors ${active ? "text-white" : "text-slate-400 hover:text-white"}`}>
285	      {children}
286	    </Link>
287	  );
288	}
