1	import Link from "next/link";
2	import { Reveal } from "./Reveal";
3	import { IconArrow, IconCheck } from "./icons";
4	
5	export function SectionHeading({
6	  label,
7	  title,
8	  sub,
9	  center = true,
10	}: {
11	  label?: string;
12	  title: React.ReactNode;
13	  sub?: React.ReactNode;
14	  center?: boolean;
15	}) {
16	  return (
17	    <div className={`${center ? "mx-auto max-w-2xl text-center" : "max-w-2xl"}`}>
18	      {label && <p className="section-label mb-3">{label}</p>}
19	      <h2 className="text-3xl font-bold tracking-tight text-[var(--fg)] sm:text-4xl">{title}</h2>
20	      {sub && <p className="mt-4 text-lg leading-relaxed text-[var(--fg-muted)]">{sub}</p>}
21	    </div>
22	  );
