"use client";

import { useEffect, useState } from "react";

/**
 * Returns `true` when the visitor prefers reduced motion, and `false` otherwise.
 *
 * SSR-safe: starts `true` (the calm, motion-free default) until the client can
 * read the media query, so the heavy Matrix animations never fire before we
 * know the visitor's preference. Live-updates if the OS setting changes.
 */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(true);

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const apply = () => setReduced(mq.matches);
    apply();
    mq.addEventListener?.("change", apply);
    return () => mq.removeEventListener?.("change", apply);
  }, []);

  return reduced;
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { useReducedMotion } from "./useReducedMotion";

/**
 * Hero visual for the Matrix page: a grid of six small build consoles that type
 * a prompt, stream a build, and light up "LIVE" in a cascade — evoking many
 * projects building at once, in parallel, on the customer's own servers.
 *
 * Cheap to render: a single interval ticks a frame counter; every pane derives
 * its visible state as a *pure function* of that frame from a precomputed
 * timeline (no per-pane timers, no layout thrash). Fully gated on
 * prefers-reduced-motion — reduced-motion visitors see every console at its
 * finished, "LIVE" resting state with no motion at all.
 */

type Kind = "you" | "run" | "ok" | "dim";
type Line = { kind: Kind; text: string };

type Project = {
  name: string;
  accent: string; // tailwind text color for the LIVE dot + name
  glow: string; // rgba used for the active glow ring
  script: Line[];
};

const PROJECTS: Project[] = [
  {
