    accent: "text-sky-300",
    glow: "56,189,248",
    script: [
      { kind: "you", text: "A landing page for my SaaS" },
      { kind: "run", text: "generating hero + pricing" },
      { kind: "ok", text: "Next.js + Tailwind scaffolded" },
      { kind: "ok", text: "deployed to :3000" },
      { kind: "ok", text: "LIVE" },
    ],
  },
  {
    name: "discord-bot",
    accent: "text-violet-300",
    glow: "167,139,250",
    script: [
      { kind: "you", text: "A Discord mod bot with slash cmds" },
