    ],
  },
  {
    name: "crm-tool",
    accent: "text-amber-300",
    glow: "252,211,77",
    script: [
      { kind: "you", text: "Internal CRM with a deals board" },
      { kind: "run", text: "building contacts + pipeline" },
      { kind: "ok", text: "auth + roles configured" },
