      { kind: "ok", text: "referral counter added" },
      { kind: "ok", text: "LIVE" },
    ],
  },
];

/* -------------------------------------------------------------------------- */
/* Precomputed per-pane timeline: pure function of the global frame counter.   */
/* -------------------------------------------------------------------------- */

type RLine = { kind: Kind; text: string; caret?: boolean };
type Frame = { lines: RLine[]; active: boolean; live: boolean };

const HOLD_LIVE = 10; // frames the finished console stays "LIVE" before looping
const LEAD_IN = 3; // blank frames before typing starts

function buildTimeline(script: Line[]): Frame[] {
  const frames: Frame[] = [];
  const [prompt, ...rest] = script;

  // Lead-in: dim idle console.
  for (let i = 0; i < LEAD_IN; i++) {
    frames.push({ lines: [{ kind: "dim", text: "waiting for a task…" }], active: false, live: false });
  }
  // Type the prompt character by character.
  for (let c = 1; c <= prompt.text.length; c++) {
    frames.push({
      lines: [{ kind: "you", text: prompt.text.slice(0, c), caret: true }],
      active: true,
      live: false,
    });
  }
  // Stream the remaining build lines, one revealed per frame (with a couple of
  // dwell frames each so the eye can follow).
  for (let r = 0; r < rest.length; r++) {
    const revealed: RLine[] = [{ kind: prompt.kind, text: prompt.text }];
    for (let k = 0; k <= r; k++) revealed.push({ kind: rest[k].kind, text: rest[k].text });
    const live = r === rest.length - 1;
    const dwell = live ? HOLD_LIVE : 2;
    for (let d = 0; d < dwell; d++) {
      frames.push({ lines: revealed.slice(-4), active: true, live });
    }
  }
  return frames;
}

const TIMELINES = PROJECTS.map((p) => buildTimeline(p.script));
// Stagger each pane so the grid lights up as a wave rather than in lockstep.
const OFFSETS = PROJECTS.map((_, i) => i * 9);

const PREFIX: Record<Kind, string> = { you: "› ", run: "◆ ", ok: "✓ ", dim: "" };
const COLOR: Record<Kind, string> = {
  you: "text-slate-200",
  run: "text-brand-300",
  ok: "text-emerald-400",
  dim: "text-slate-600",
};

function Pane({ project, timeline, frame }: { project: Project; timeline: Frame[]; frame: number }) {
  const state = timeline[frame % timeline.length];
  return (
    <div
      className="relative overflow-hidden rounded-xl border bg-[#080c17]/90 transition-[border-color,box-shadow,transform] duration-500"
      style={{
        borderColor: state.active ? `rgba(${project.glow},0.4)` : "rgba(255,255,255,0.07)",
        boxShadow: state.active ? `0 0 0 1px rgba(${project.glow},0.12), 0 12px 30px -12px rgba(${project.glow},0.4)` : "none",
      }}
    >
      <div className="flex items-center gap-1.5 border-b border-white/[0.06] px-2.5 py-1.5">
        <span
          className={`h-1.5 w-1.5 rounded-full ${state.live ? project.accent : "text-slate-600"}`}
          style={{ background: "currentColor", boxShadow: state.live ? "0 0 6px currentColor" : "none" }}
        />
        <span className={`truncate text-[10px] font-semibold ${state.active ? project.accent : "text-slate-500"}`}>
          {project.name}
        </span>
        {state.live && (
          <span className="ml-auto rounded-full bg-emerald-500/15 px-1.5 py-px text-[8px] font-bold uppercase tracking-wider text-emerald-300">
            live
          </span>
        )}
      </div>
      <pre className="h-[104px] overflow-hidden px-2.5 py-2 font-mono text-[10px] leading-[1.45]">
        {state.lines.map((l, i) => (
          <div key={i} className={`truncate ${COLOR[l.kind]}`}>
            <span className="select-none opacity-70">{PREFIX[l.kind]}</span>
            {l.text}
            {l.caret && <span className="ml-px inline-block w-[5px] animate-blink bg-brand-300 align-middle" style={{ height: "0.85em" }} />}
          </div>
        ))}
