    </div>
  );
}

export function ConsoleMatrix() {
  const reduced = useReducedMotion();
  const [frame, setFrame] = useState(0);
  const raf = useRef<number | null>(null);

  useEffect(() => {
    if (reduced) return;
    const id = setInterval(() => setFrame((f) => f + 1), 120);
    return () => clearInterval(id);
  }, [reduced]);

  // Resting state for reduced motion: hold the very last frame of every timeline
  // so all six consoles read as finished + "LIVE" with zero animation.
  const restFrame = useMemo(() => 10_000, []);

  return (
    <div
      className="relative rounded-2xl border border-white/10 bg-[#050813]/80 p-3 shadow-2xl shadow-black/50 backdrop-blur-sm sm:p-4"
      role="img"
      aria-label="Six AI build consoles running in parallel — each building a different project on its own server, lighting up as it goes live."
    >
      <div className="mb-3 flex items-center justify-between px-1">
