          <span className="h-2.5 w-2.5 rounded-full bg-[#ff5f57]" />
          <span className="h-2.5 w-2.5 rounded-full bg-[#febc2e]" />
          <span className="h-2.5 w-2.5 rounded-full bg-[#28c840]" />
          <span className="ml-2 text-[11px] font-medium text-slate-500">Matrix · 6 consoles</span>
        </div>
        <span className="hidden text-[11px] text-slate-500 sm:inline">building in parallel</span>
      </div>
      <div className="grid grid-cols-2 gap-2.5 sm:gap-3 lg:grid-cols-3">
        {PROJECTS.map((p, i) => (
          <Pane
            key={p.name}
            project={p}
            timeline={TIMELINES[i]}
            frame={reduced ? restFrame : frame + OFFSETS[i]}
          />
        ))}
