  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { useReducedMotion } from "./useReducedMotion";

/**
 * The "watch it build" moment: one console that types a prompt, shows a plan,
 * builds it in staged (faux but believable) steps, and goes live — then loops.
 *
 * Interactive: a real, keyboard-accessible segmented control lets the visitor
 * flip between the two ways to build a console — their own Anthropic API key, or
 * the Claude CLI already installed on their VPS (Pro/Max subscription). The
 * script is identical; the header, cost note, and accent reflect the mode.
 *
 * Animation is a pure function of a frame counter and is fully gated on
 * prefers-reduced-motion, which pins the console to its finished "LIVE" frame.
 */

type Kind = "you" | "plan" | "run" | "ok" | "url";
type RLine = { kind: Kind; text: string; caret?: boolean };
type Frame = { lines: RLine[]; progress: number; status: string };

const PROMPT = "Build a paid newsletter SaaS with Stripe subscriptions and a dashboard.";

const PLAN: string[] = [
  "Next.js app + Postgres on your server",
  "Auth, subscriber list & double opt-in",
  "Stripe checkout + webhook for billing",
  "Writer dashboard with draft & send",
];

const BUILD: string[] = [
  "scaffolding Next.js + Tailwind + Prisma",
  "provisioning Postgres on the VPS",
  "wiring Stripe products & webhook",
  "building the subscriber dashboard",
  "running migrations + smoke tests",
];

const HOLD_END = 16;

function buildTimeline(): Frame[] {
  const frames: Frame[] = [];
  const push = (lines: RLine[], progress: number, status: string, n = 1) => {
    for (let i = 0; i < n; i++) frames.push({ lines, progress, status });
  };

  // 1 — type the prompt.
  for (let c = 1; c <= PROMPT.length; c++) {
    push([{ kind: "you", text: PROMPT.slice(0, c), caret: true }], 0, "Listening…");
  }
  push([{ kind: "you", text: PROMPT }], 0, "Thinking…", 4);

  // 2 — reveal the plan, line by line.
  const base: RLine[] = [{ kind: "you", text: PROMPT }, { kind: "plan", text: "Here's the plan:" }];
  push(base, 6, "Planning", 2);
  for (let p = 0; p < PLAN.length; p++) {
    const lines = [...base, ...PLAN.slice(0, p + 1).map((t) => ({ kind: "plan" as Kind, text: t }))];
    push(lines, 6 + p * 2, "Planning", 3);
  }

  // 3 — approved, then stream the build with a growing progress bar.
  const planned: RLine[] = [...base, ...PLAN.map((t) => ({ kind: "plan" as Kind, text: t }))];
  push([...planned, { kind: "ok", text: "plan approved — building on srv-sg-01" }], 16, "Approved", 3);
  for (let b = 0; b < BUILD.length; b++) {
    const visible: RLine[] = [
      { kind: "run", text: BUILD[b], caret: true },
      ...BUILD.slice(0, b).map((t) => ({ kind: "ok" as Kind, text: t })),
    ];
    const progress = 20 + Math.round(((b + 1) / BUILD.length) * 72);
    push(visible.slice(0, 6), progress, `Building ${progress}%`, 5);
  }

  // 4 — live.
  const done: RLine[] = [
    { kind: "url", text: "LIVE → https://ink-letter.app" },
    ...BUILD.map((t) => ({ kind: "ok" as Kind, text: t })),
  ];
  push(done.slice(0, 6), 100, "Live", HOLD_END);

  return frames;
}

const TIMELINE = buildTimeline();

const PREFIX: Record<Kind, string> = { you: "you › ", plan: "  ", run: "◆ ", ok: "✓ ", url: "★ " };
const COLOR: Record<Kind, string> = {
  you: "text-amber-200",
  plan: "text-slate-300",
  run: "text-brand-300",
  ok: "text-emerald-400",
  url: "text-emerald-300 font-semibold",
};

type Mode = "key" | "cli";

const MODES: Record<Mode, { label: string; header: string; note: string }> = {
  key: {
    label: "Your API key",
    header: "claude · your Anthropic API key",
    note: "Billed to your key — a whole app is often just a few dollars of API.",
  },
  cli: {
    label: "Your server's Claude",
    header: "claude cli · Pro / Max subscription",
    note: "Runs the CLI pre-installed on your VPS — unlimited on your flat subscription.",
  },
};

export function LiveBuildConsole() {
  const reduced = useReducedMotion();
  const [frame, setFrame] = useState(0);
  const [mode, setMode] = useState<Mode>("key");

  useEffect(() => {
    if (reduced) return;
    const id = setInterval(() => setFrame((f) => f + 1), 90);
    return () => clearInterval(id);
  }, [reduced]);

  const state = reduced ? TIMELINE[TIMELINE.length - 1] : TIMELINE[frame % TIMELINE.length];
  const m = MODES[mode];

  return (
    <div className="overflow-hidden rounded-2xl border border-white/10 bg-[#080c17] shadow-2xl shadow-black/50">
      {/* chrome + mode toggle */}
      <div className="flex flex-wrap items-center gap-3 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
        <span className="h-3 w-3 rounded-full bg-[#ff5f57]" />
        <span className="h-3 w-3 rounded-full bg-[#febc2e]" />
        <span className="h-3 w-3 rounded-full bg-[#28c840]" />
        <span className="ml-1 truncate text-[11px] font-medium text-slate-500">{m.header}</span>
        <div
          role="group"
          aria-label="Choose how this console runs"
          className="ml-auto inline-flex rounded-lg border border-white/10 bg-black/30 p-0.5"
        >
          {(Object.keys(MODES) as Mode[]).map((k) => (
            <button
              key={k}
              type="button"
              aria-pressed={mode === k}
              onClick={() => setMode(k)}
              className={`rounded-md px-2.5 py-1 text-[11px] font-semibold transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand-400 ${
                mode === k ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white" : "text-slate-400 hover:text-white"
              }`}
            >
              {MODES[k].label}
            </button>
          ))}
        </div>
      </div>

      {/* body */}
      <pre className="h-[240px] overflow-hidden px-5 py-4 font-mono text-[12.5px] leading-relaxed sm:h-[248px]">
        {state.lines.map((l, i) => (
          <div key={i} className={COLOR[l.kind]}>
            <span className="select-none opacity-70">{PREFIX[l.kind]}</span>
            {l.text}
            {l.caret && <span className="ml-0.5 inline-block h-[1em] w-[6px] animate-blink bg-brand-300 align-text-bottom" />}
          </div>
        ))}
      </pre>

      {/* status + progress */}
      <div className="border-t border-white/[0.06] px-5 py-3">
        <div className="flex items-center justify-between text-[11px]">
          <span className="font-semibold text-slate-300">{state.status}</span>
          <span className="text-slate-500">{state.progress}%</span>
        </div>
        <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-white/[0.06]">
          <div
            className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 transition-[width] duration-200 ease-out"
            style={{ width: `${state.progress}%` }}
          />
        </div>
        <p className="mt-3 text-[11px] leading-relaxed text-slate-500">{m.note}</p>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useReducedMotion } from "./useReducedMotion";

/**
 * A build board that tracks each project's status as it moves Queued → Planning
 * → Building → Live, several at once — the parallel-builds showcase. Each row is
 * offset so the board feels alive without lockstep. Pure function of a frame
 * counter; reduced-motion visitors see every project already "Live".
 */

type Stage = { label: string; tone: string; dot: string };

const STAGES: Stage[] = [
  { label: "Queued", tone: "text-slate-400 bg-white/[0.05]", dot: "bg-slate-500" },
  { label: "Planning", tone: "text-sky-300 bg-sky-500/10", dot: "bg-sky-400" },
  { label: "Building", tone: "text-brand-200 bg-brand-500/12", dot: "bg-brand-400 animate-pulse" },
  { label: "Live", tone: "text-emerald-300 bg-emerald-500/12", dot: "bg-emerald-400" },
];

type Row = { name: string; server: string; kind: string };

const ROWS: Row[] = [
  { name: "ink-letter", server: "srv-sg-01", kind: "SaaS · Stripe" },
  { name: "orders-api", server: "srv-sg-02", kind: "REST API" },
  { name: "guild-bot", server: "srv-sg-01", kind: "Discord bot" },
  { name: "studio-site", server: "srv-sg-03", kind: "Landing page" },
  { name: "backup-cron", server: "srv-sg-02", kind: "Automation" },
];

// Frames-per-stage the row dwells in, then it advances. Offsets stagger the rows.
const DWELL = 22;
const OFFSETS = ROWS.map((_, i) => i * 7);

function rowState(frame: number): { stage: number; pct: number } {
  const total = STAGES.length * DWELL;
  const t = frame % total;
  const stage = Math.min(STAGES.length - 1, Math.floor(t / DWELL));
  const within = (t % DWELL) / DWELL;
  // Progress ramps across Planning/Building; full at Live, empty when Queued.
  const pct =
    stage === 0 ? 4 : stage === STAGES.length - 1 ? 100 : Math.round(((stage - 1 + within) / (STAGES.length - 2)) * 96) + 4;
  return { stage, pct };
}

export function BuildBoard() {
  const reduced = useReducedMotion();
  const [frame, setFrame] = useState(0);

  useEffect(() => {
    if (reduced) return;
    const id = setInterval(() => setFrame((f) => f + 1), 140);
    return () => clearInterval(id);
  }, [reduced]);

  return (
    <div className="overflow-hidden rounded-2xl border border-white/10 bg-navy-900/70 shadow-2xl shadow-black/40 backdrop-blur-md">
      <div className="flex items-center justify-between border-b border-white/[0.06] px-4 py-3 sm:px-5">
        <span className="text-sm font-semibold text-white">Build board</span>
        <span className="text-[11px] text-slate-500">5 projects · 3 servers</span>
      </div>
      <div className="divide-y divide-white/[0.05]">
        {ROWS.map((r, i) => {
          const { stage, pct } = reduced ? { stage: STAGES.length - 1, pct: 100 } : rowState(frame + OFFSETS[i]);
          const s = STAGES[stage];
          return (
            <div key={r.name} className="flex items-center gap-3 px-4 py-3 sm:gap-4 sm:px-5">
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2">
                  <span className="truncate font-mono text-[13px] font-medium text-slate-100">{r.name}</span>
                  <span className="hidden truncate text-[11px] text-slate-500 sm:inline">{r.kind}</span>
                </div>
                <div className="mt-1.5 h-1 w-full max-w-[220px] overflow-hidden rounded-full bg-white/[0.06]">
                  <div
                    className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 transition-[width] duration-300 ease-out"
                    style={{ width: `${pct}%` }}
                  />
                </div>
              </div>
              <span className="hidden font-mono text-[11px] text-slate-500 md:inline">{r.server}</span>
              <span className={`inline-flex shrink-0 items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold ${s.tone}`}>
                <span className={`h-1.5 w-1.5 rounded-full ${s.dot}`} />
                {s.label}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

